INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('1','launch-1','Welcome to Digimon NXT','The NXT Network is online. Explore 264 Dawn locations at their supplied native image resolution, battle wild Digimon, secure scan data on contact and materialize new partners.','system','1789794058','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('2','launch-2','DigiLab Materialization Protocol','Scan data is species-specific. Reach 100% scan data to materialize a persistent Digimon instance. Conversion uses all accumulated scan data. Every 20% above 100% grants 1 starting ABI, up to 5 at 200%.','research','1789880458','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('3','launch-3','Paradox Signals Detected','The roster now contains 1,000 supplied forms. Paradox signals have a 0.2% chance per wild encounter, 1.75 times base stats, and yield only 1–3% scan data. Command a team of three and build ABI through evolution. Your full party recovers after every battle.','research','1789966858','1');
INSERT INTO `news` (`id`,`slug`,`title`,`body`,`category`,`published_at`,`is_published`) VALUES ('4','launch-4','Multiplayer Presence Active','Tamers sharing the same Cyberspace sector are synchronized through the map presence service. Movement remains server validated against the sector collision grid.','network','1790053258','1');
INSERT INTO `events` (`id`,`slug`,`name`,`area_name`,`description`,`starts_at`,`ends_at`,`is_active`) VALUES ('1','cyber-route-sweep','Dawn Trail Survey','Dawn Trails','Win wild battles along the Dawn trails to stabilize the local network.','0','0','1');
