-- Digimon NXT v0.7.0: FRESH installation only.
-- Existing saves: use _setup.php > Create / Repair Schema to apply the upgrade.
-- 1000 forms, 768 moves in JSON, schema revision 8. Includes 1000 AI-only rival accounts; bot login is disabled.
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;
CREATE DATABASE IF NOT EXISTS `digimon_nxt` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `digimon_nxt`;

CREATE TABLE IF NOT EXISTS `arena_battles` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `opponent_key` varchar(64) NOT NULL,
  `opponent_name` varchar(100) NOT NULL,
  `result` enum('win','loss') NOT NULL,
  `rating_before` int(10) unsigned NOT NULL,
  `rating_after` int(10) unsigned NOT NULL,
  `bits_gain` int(10) unsigned NOT NULL DEFAULT 0,
  `exp_gain` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_arena_owner` (`owner_id`,`created_at`),
  CONSTRAINT `fk_arena_battle_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `arena_progress` (
  `owner_id` int(10) unsigned NOT NULL,
  `rating` int(10) unsigned NOT NULL DEFAULT 1000,
  `wins` int(10) unsigned NOT NULL DEFAULT 0,
  `losses` int(10) unsigned NOT NULL DEFAULT 0,
  `streak` int(10) unsigned NOT NULL DEFAULT 0,
  `best_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`owner_id`),
  CONSTRAINT `fk_arena_progress_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `audit_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `actor_id` int(10) unsigned DEFAULT NULL,
  `action` varchar(80) NOT NULL,
  `details` varchar(500) NOT NULL DEFAULT '',
  `ip` varchar(64) NOT NULL DEFAULT '',
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_audit_actor` (`actor_id`,`created_at`),
  CONSTRAINT `fk_audit_actor` FOREIGN KEY (`actor_id`) REFERENCES `members` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `battle_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `digimon_id` bigint(20) unsigned DEFAULT NULL,
  `enemy_species_id` int(10) unsigned DEFAULT NULL,
  `battle_type` enum('wild','arena','event') NOT NULL DEFAULT 'wild',
  `result` enum('win','loss','disconnect') NOT NULL,
  `area_key` varchar(64) NOT NULL DEFAULT '',
  `exp_gain` int(10) unsigned NOT NULL DEFAULT 0,
  `scan_gain` smallint(5) unsigned NOT NULL DEFAULT 0,
  `bits_gain` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_battle_owner` (`owner_id`,`created_at`),
  KEY `fk_battle_digimon` (`digimon_id`),
  KEY `fk_battle_enemy` (`enemy_species_id`),
  CONSTRAINT `fk_battle_digimon` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_battle_enemy` FOREIGN KEY (`enemy_species_id`) REFERENCES `digimon_species` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_battle_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `clan_members` (
  `clan_id` int(10) unsigned NOT NULL,
  `user_id` int(10) unsigned NOT NULL,
  `member_rank` enum('leader','officer','member') NOT NULL DEFAULT 'member',
  `joined_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`clan_id`,`user_id`),
  UNIQUE KEY `user_id` (`user_id`),
  CONSTRAINT `fk_clan_member_clan` FOREIGN KEY (`clan_id`) REFERENCES `clans` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_clan_member_user` FOREIGN KEY (`user_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `clans` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(80) NOT NULL,
  `tag` varchar(8) NOT NULL,
  `description` varchar(500) NOT NULL DEFAULT '',
  `owner_id` int(10) unsigned NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `name` (`name`),
  UNIQUE KEY `tag` (`tag`),
  KEY `fk_clan_owner` (`owner_id`),
  CONSTRAINT `fk_clan_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_action_receipts` (
  `owner_id` int(10) unsigned NOT NULL,
  `token` char(48) NOT NULL,
  `result_text` varchar(500) NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`owner_id`,`token`),
  CONSTRAINT `fk_receipt_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_battle_state` (
  `owner_id` int(10) unsigned NOT NULL,
  `state_json` longtext NOT NULL,
  `updated_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`owner_id`),
  CONSTRAINT `fk_active_battle_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_instances` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `species_id` int(10) unsigned NOT NULL,
  `nickname` varchar(100) NOT NULL DEFAULT '',
  `level` int(10) unsigned NOT NULL DEFAULT 1,
  `exp` bigint(20) unsigned NOT NULL DEFAULT 0,
  `hp` int(10) unsigned NOT NULL DEFAULT 1,
  `max_hp` int(10) unsigned NOT NULL DEFAULT 1,
  `sp` int(10) unsigned NOT NULL DEFAULT 30,
  `max_sp` int(10) unsigned NOT NULL DEFAULT 30,
  `attack_stat` int(10) unsigned NOT NULL DEFAULT 1,
  `defense_stat` int(10) unsigned NOT NULL DEFAULT 1,
  `speed_stat` int(10) unsigned NOT NULL DEFAULT 1,
  `personality` varchar(32) NOT NULL DEFAULT 'Balanced',
  `source` varchar(32) NOT NULL DEFAULT 'materialized',
  `locked_trade` tinyint(1) NOT NULL DEFAULT 0,
  `created_at` int(10) unsigned NOT NULL DEFAULT 0,
  `abi` smallint(5) unsigned NOT NULL DEFAULT 0,
  `cam` tinyint(3) unsigned NOT NULL DEFAULT 0,
  `intelligence_stat` int(10) unsigned NOT NULL DEFAULT 1,
  `training_json` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_owner` (`owner_id`),
  KEY `idx_species` (`species_id`),
  CONSTRAINT `fk_digimon_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_digimon_species` FOREIGN KEY (`species_id`) REFERENCES `digimon_species` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_learned_moves` (
  `digimon_id` bigint(20) unsigned NOT NULL,
  `move_slug` varchar(100) NOT NULL,
  PRIMARY KEY (`digimon_id`,`move_slug`),
  CONSTRAINT `fk_learned_instance` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_party` (
  `owner_id` int(10) unsigned NOT NULL,
  `slot` tinyint(3) unsigned NOT NULL,
  `digimon_id` bigint(20) unsigned NOT NULL,
  PRIMARY KEY (`owner_id`,`slot`),
  UNIQUE KEY `uq_party_digimon` (`owner_id`,`digimon_id`),
  KEY `fk_party_instance` (`digimon_id`),
  CONSTRAINT `fk_party_instance` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_party_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_scan` (
  `owner_id` int(10) unsigned NOT NULL,
  `species_id` int(10) unsigned NOT NULL,
  `scan_percent` smallint(5) unsigned NOT NULL DEFAULT 0,
  `encounters` int(10) unsigned NOT NULL DEFAULT 0,
  `wins` int(10) unsigned NOT NULL DEFAULT 0,
  `first_seen` int(10) unsigned NOT NULL DEFAULT 0,
  `last_seen` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`owner_id`,`species_id`),
  KEY `idx_scan_ready` (`owner_id`,`scan_percent`),
  KEY `fk_scan_species` (`species_id`),
  CONSTRAINT `fk_scan_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_scan_species` FOREIGN KEY (`species_id`) REFERENCES `digimon_species` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digimon_species` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(80) NOT NULL,
  `name` varchar(100) NOT NULL,
  `stage` varchar(24) NOT NULL,
  `attribute` varchar(24) NOT NULL,
  `type` varchar(45) NOT NULL,
  `element` varchar(24) NOT NULL,
  `base_hp` int(10) unsigned NOT NULL,
  `base_attack` int(10) unsigned NOT NULL,
  `base_defense` int(10) unsigned NOT NULL,
  `base_speed` int(10) unsigned NOT NULL,
  `skill_name` varchar(100) NOT NULL,
  `skill_power` int(10) unsigned NOT NULL,
  `sprite` varchar(180) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `name` (`name`),
  KEY `idx_stage` (`stage`),
  KEY `idx_attribute` (`attribute`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `digivolution_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `digimon_id` bigint(20) unsigned NOT NULL,
  `from_species_id` int(10) unsigned NOT NULL,
  `to_species_id` int(10) unsigned NOT NULL,
  `level_at_change` int(10) unsigned NOT NULL,
  `bits_spent` int(10) unsigned NOT NULL DEFAULT 0,
  `created_at` int(10) unsigned NOT NULL,
  `abi_gained` smallint(5) unsigned NOT NULL DEFAULT 0,
  `direction` varchar(8) NOT NULL DEFAULT 'up',
  PRIMARY KEY (`id`),
  KEY `idx_digivolution_owner` (`owner_id`,`created_at`),
  KEY `fk_digivolution_instance` (`digimon_id`),
  KEY `fk_digivolution_from` (`from_species_id`),
  KEY `fk_digivolution_to` (`to_species_id`),
  CONSTRAINT `fk_digivolution_from` FOREIGN KEY (`from_species_id`) REFERENCES `digimon_species` (`id`),
  CONSTRAINT `fk_digivolution_instance` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_digivolution_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_digivolution_to` FOREIGN KEY (`to_species_id`) REFERENCES `digimon_species` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `event_progress` (
  `owner_id` int(10) unsigned NOT NULL,
  `event_id` int(10) unsigned NOT NULL,
  `progress` int(10) unsigned NOT NULL DEFAULT 0,
  `completed` tinyint(1) NOT NULL DEFAULT 0,
  `updated_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`owner_id`,`event_id`),
  KEY `fk_event_progress_event` (`event_id`),
  CONSTRAINT `fk_event_progress_event` FOREIGN KEY (`event_id`) REFERENCES `events` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_event_progress_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `events` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) NOT NULL,
  `name` varchar(140) NOT NULL,
  `area_name` varchar(100) NOT NULL,
  `description` varchar(500) NOT NULL,
  `starts_at` int(10) unsigned NOT NULL DEFAULT 0,
  `ends_at` int(10) unsigned NOT NULL DEFAULT 0,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `friends` (
  `user_low` int(10) unsigned NOT NULL,
  `user_high` int(10) unsigned NOT NULL,
  `status` enum('pending','accepted','blocked') NOT NULL DEFAULT 'pending',
  `requested_by` int(10) unsigned NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  `updated_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`user_low`,`user_high`),
  KEY `idx_friend_status` (`status`),
  KEY `fk_friend_high` (`user_high`),
  KEY `fk_friend_requester` (`requested_by`),
  CONSTRAINT `fk_friend_high` FOREIGN KEY (`user_high`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_friend_low` FOREIGN KEY (`user_low`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_friend_requester` FOREIGN KEY (`requested_by`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `items` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(80) NOT NULL,
  `name` varchar(100) NOT NULL,
  `category` varchar(40) NOT NULL,
  `description` varchar(255) NOT NULL,
  `price` int(10) unsigned NOT NULL DEFAULT 0,
  `stack_limit` int(10) unsigned NOT NULL DEFAULT 99,
  `icon_code` varchar(16) NOT NULL DEFAULT 'ITEM',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  UNIQUE KEY `name` (`name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `login_trys` (
  `ip` varchar(64) NOT NULL,
  `username` varchar(45) NOT NULL DEFAULT '',
  `time` int(10) unsigned NOT NULL DEFAULT 0,
  `attempts` tinyint(3) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`ip`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `mapusers` (
  `id` int(10) unsigned NOT NULL,
  `username` varchar(45) NOT NULL,
  `tamer` smallint(5) unsigned NOT NULL DEFAULT 1,
  `world_key` varchar(24) NOT NULL DEFAULT 'cyberspace',
  `map` varchar(64) NOT NULL DEFAULT 'dawn-001',
  `x` int(11) NOT NULL DEFAULT 25,
  `y` int(11) NOT NULL DEFAULT 18,
  `time` time DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_map_area` (`world_key`,`map`),
  CONSTRAINT `fk_mapuser_member` FOREIGN KEY (`id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `materialization_log` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `species_id` int(10) unsigned NOT NULL,
  `digimon_id` bigint(20) unsigned NOT NULL,
  `scan_spent` smallint(5) unsigned NOT NULL DEFAULT 100,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_materialize_owner` (`owner_id`,`created_at`),
  KEY `fk_materialize_species` (`species_id`),
  KEY `fk_materialize_instance` (`digimon_id`),
  CONSTRAINT `fk_materialize_instance` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_materialize_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_materialize_species` FOREIGN KEY (`species_id`) REFERENCES `digimon_species` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `member_items` (
  `owner_id` int(10) unsigned NOT NULL,
  `item_id` int(10) unsigned NOT NULL,
  `quantity` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`owner_id`,`item_id`),
  KEY `fk_member_item_item` (`item_id`),
  CONSTRAINT `fk_member_item_item` FOREIGN KEY (`item_id`) REFERENCES `items` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_member_item_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `members` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `username` varchar(45) NOT NULL,
  `password` varchar(255) NOT NULL,
  `email` varchar(160) NOT NULL,
  `role` enum('tamer','moderator','admin') NOT NULL DEFAULT 'tamer',
  `registered` int(10) unsigned NOT NULL DEFAULT 0,
  `llogin` int(10) unsigned NOT NULL DEFAULT 0,
  `last_login` varchar(45) NOT NULL DEFAULT '',
  `ip` varchar(64) NOT NULL DEFAULT '',
  `banned` tinyint(1) NOT NULL DEFAULT 0,
  `memonmap` tinyint(1) NOT NULL DEFAULT 1,
  `messonoff` tinyint(1) NOT NULL DEFAULT 1,
  `messnotifyonoff` tinyint(1) NOT NULL DEFAULT 1,
  `money` int(11) NOT NULL DEFAULT 5000,
  `battle` int(10) unsigned NOT NULL DEFAULT 0,
  `wins` int(10) unsigned NOT NULL DEFAULT 0,
  `losses` int(10) unsigned NOT NULL DEFAULT 0,
  `totalexp` bigint(20) unsigned NOT NULL DEFAULT 0,
  `points` int(10) unsigned NOT NULL DEFAULT 0,
  `time` int(10) unsigned NOT NULL DEFAULT 0,
  `bio` varchar(500) NOT NULL DEFAULT '',
  `created_avatar` smallint(5) unsigned NOT NULL DEFAULT 1,
  `session_version` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_members_username` (`username`),
  KEY `idx_members_registered` (`registered`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `members_options` (
  `id` int(10) unsigned NOT NULL,
  `tamer` smallint(5) unsigned NOT NULL DEFAULT 1,
  `memonmap` tinyint(1) NOT NULL DEFAULT 1,
  `messonoff` tinyint(1) NOT NULL DEFAULT 1,
  `messnotifyonoff` tinyint(1) NOT NULL DEFAULT 1,
  `battle_animation` tinyint(1) NOT NULL DEFAULT 1,
  `compact_ui` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_options_member` FOREIGN KEY (`id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `messages` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `sender_id` int(10) unsigned NOT NULL,
  `recipient_id` int(10) unsigned NOT NULL,
  `subject` varchar(120) NOT NULL,
  `body` text NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  `read_at` int(10) unsigned DEFAULT NULL,
  `sender_deleted` tinyint(1) NOT NULL DEFAULT 0,
  `recipient_deleted` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_msg_recipient` (`recipient_id`,`recipient_deleted`,`created_at`),
  KEY `idx_msg_sender` (`sender_id`,`sender_deleted`,`created_at`),
  CONSTRAINT `fk_msg_recipient` FOREIGN KEY (`recipient_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_msg_sender` FOREIGN KEY (`sender_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `news` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `slug` varchar(100) NOT NULL,
  `title` varchar(160) NOT NULL,
  `body` text NOT NULL,
  `category` varchar(32) NOT NULL DEFAULT 'system',
  `published_at` int(10) unsigned NOT NULL,
  `is_published` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `slug` (`slug`),
  KEY `idx_news_publish` (`is_published`,`published_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `notifications` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `category` varchar(32) NOT NULL DEFAULT 'system',
  `title` varchar(120) NOT NULL,
  `body` varchar(500) NOT NULL,
  `link` varchar(180) NOT NULL DEFAULT '',
  `created_at` int(10) unsigned NOT NULL,
  `read_at` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_notify_owner` (`owner_id`,`read_at`,`created_at`),
  CONSTRAINT `fk_notify_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_bot_activity` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `owner_id` int(10) unsigned NOT NULL,
  `action` varchar(24) NOT NULL,
  `summary` varchar(255) NOT NULL,
  `detail_json` mediumtext NOT NULL,
  `match_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_nxt_activity_owner` (`owner_id`,`id`),
  KEY `idx_nxt_activity_action` (`action`,`id`),
  KEY `idx_nxt_activity_time` (`created_at`),
  CONSTRAINT `fk_nxt_activity_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_bots` (
  `owner_id` int(10) unsigned NOT NULL,
  `bot_no` smallint(5) unsigned NOT NULL,
  `activity_step` int(10) unsigned NOT NULL DEFAULT 0,
  `last_active` int(10) unsigned NOT NULL DEFAULT 0,
  `next_action_at` int(10) unsigned NOT NULL DEFAULT 0,
  `last_area` varchar(64) NOT NULL DEFAULT 'cyber-route',
  `wild_wins` int(10) unsigned NOT NULL DEFAULT 0,
  `wild_losses` int(10) unsigned NOT NULL DEFAULT 0,
  `materialized` int(10) unsigned NOT NULL DEFAULT 0,
  `party_changes` int(10) unsigned NOT NULL DEFAULT 0,
  `evolutions` int(10) unsigned NOT NULL DEFAULT 0,
  `enabled` tinyint(4) NOT NULL DEFAULT 1,
  PRIMARY KEY (`owner_id`),
  UNIQUE KEY `bot_no` (`bot_no`),
  KEY `idx_bot_due` (`enabled`,`next_action_at`,`bot_no`),
  CONSTRAINT `fk_nxt_bot_member` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_ranked_matches` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `request_token` char(64) NOT NULL,
  `season_id` int(10) unsigned NOT NULL,
  `attacker_id` int(10) unsigned NOT NULL,
  `defender_id` int(10) unsigned NOT NULL,
  `result` enum('win','loss','draw') NOT NULL,
  `points_before` int(10) unsigned NOT NULL,
  `points_after` int(10) unsigned NOT NULL,
  `bits_gain` int(10) unsigned NOT NULL,
  `exp_gain` int(10) unsigned NOT NULL,
  `medals_gain` smallint(5) unsigned NOT NULL,
  `rounds` smallint(5) unsigned NOT NULL,
  `attacker_json` mediumtext NOT NULL,
  `defender_json` mediumtext NOT NULL,
  `battle_json` mediumtext NOT NULL,
  `created_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `request_token` (`request_token`),
  KEY `idx_nxt_match_attacker` (`attacker_id`,`id`),
  KEY `idx_nxt_match_defender` (`defender_id`,`id`),
  KEY `idx_nxt_match_pair` (`attacker_id`,`defender_id`,`created_at`),
  KEY `idx_nxt_match_season` (`season_id`,`id`),
  CONSTRAINT `fk_nxt_match_attacker` FOREIGN KEY (`attacker_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_nxt_match_defender` FOREIGN KEY (`defender_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_ranked_profiles` (
  `owner_id` int(10) unsigned NOT NULL,
  `energy` tinyint(3) unsigned NOT NULL DEFAULT 5,
  `energy_at` int(10) unsigned NOT NULL DEFAULT 0,
  `wins` int(10) unsigned NOT NULL DEFAULT 0,
  `losses` int(10) unsigned NOT NULL DEFAULT 0,
  `draws` int(10) unsigned NOT NULL DEFAULT 0,
  `medals` int(10) unsigned NOT NULL DEFAULT 0,
  `joined_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`owner_id`),
  CONSTRAINT `fk_nxt_ranked_member` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_ranked_seasons` (
  `season_id` int(10) unsigned NOT NULL,
  `owner_id` int(10) unsigned NOT NULL,
  `points` int(10) unsigned NOT NULL DEFAULT 0,
  `wins` int(10) unsigned NOT NULL DEFAULT 0,
  `losses` int(10) unsigned NOT NULL DEFAULT 0,
  `draws` int(10) unsigned NOT NULL DEFAULT 0,
  `streak` int(10) unsigned NOT NULL DEFAULT 0,
  `best_streak` int(10) unsigned NOT NULL DEFAULT 0,
  `defense_wins` int(10) unsigned NOT NULL DEFAULT 0,
  `defense_losses` int(10) unsigned NOT NULL DEFAULT 0,
  `reward_claimed` tinyint(4) NOT NULL DEFAULT 0,
  `final_rank` int(10) unsigned NOT NULL DEFAULT 0,
  `season_closed_at` int(10) unsigned NOT NULL DEFAULT 0,
  `updated_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`season_id`,`owner_id`),
  KEY `idx_nxt_season_board` (`season_id`,`points`,`wins`,`owner_id`),
  KEY `fk_nxt_season_member` (`owner_id`),
  CONSTRAINT `fk_nxt_season_member` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_ranked_tickets` (
  `token` char(64) NOT NULL,
  `owner_id` int(10) unsigned NOT NULL,
  `defender_id` int(10) unsigned NOT NULL,
  `defender_json` mediumtext NOT NULL,
  `season_id` int(10) unsigned NOT NULL,
  `expires_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`token`),
  UNIQUE KEY `owner_id` (`owner_id`),
  KEY `fk_nxt_ticket_defender` (`defender_id`),
  CONSTRAINT `fk_nxt_ticket_defender` FOREIGN KEY (`defender_id`) REFERENCES `members` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_nxt_ticket_owner` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_worker_state` (
  `worker_key` varchar(40) NOT NULL,
  `cursor_no` int(10) unsigned NOT NULL DEFAULT 0,
  `last_run` int(10) unsigned NOT NULL DEFAULT 0,
  `processed` int(10) unsigned NOT NULL DEFAULT 0,
  `last_error` varchar(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`worker_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_world_admin_audit` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `created_at` int(10) unsigned NOT NULL,
  `operator_name` varchar(120) NOT NULL,
  `command_name` varchar(64) NOT NULL,
  `target_name` varchar(80) NOT NULL DEFAULT '',
  `success` tinyint(1) NOT NULL,
  `summary` varchar(500) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_world_audit_time` (`created_at`),
  KEY `idx_world_audit_target` (`target_name`,`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_world_bans` (
  `owner_id` int(10) unsigned NOT NULL,
  `reason` varchar(255) NOT NULL,
  `banned_at` int(10) unsigned NOT NULL,
  `expires_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`owner_id`),
  KEY `idx_world_ban_expiry` (`expires_at`),
  CONSTRAINT `fk_world_ban_member` FOREIGN KEY (`owner_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_world_ip_bans` (
  `ip` varchar(45) NOT NULL,
  `reason` varchar(255) NOT NULL,
  `banned_at` int(10) unsigned NOT NULL,
  `expires_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`ip`),
  KEY `idx_world_ip_ban_expiry` (`expires_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `nxt_world_settings` (
  `setting_key` varchar(64) NOT NULL,
  `value_json` text NOT NULL,
  `updated_at` int(10) unsigned NOT NULL,
  PRIMARY KEY (`setting_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `online` (
  `id` int(10) unsigned NOT NULL,
  `username` varchar(45) NOT NULL,
  `activity` varchar(120) NOT NULL DEFAULT 'Dashboard',
  `time` int(10) unsigned NOT NULL DEFAULT 0,
  `useragent` varchar(250) NOT NULL DEFAULT '',
  `server` varchar(45) NOT NULL DEFAULT 'local',
  PRIMARY KEY (`id`),
  KEY `idx_online_time` (`time`),
  CONSTRAINT `fk_online_member` FOREIGN KEY (`id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `schema_meta` (
  `meta_key` varchar(64) NOT NULL,
  `meta_value` varchar(255) NOT NULL,
  `updated_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`meta_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `trade_listings` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `seller_id` int(10) unsigned NOT NULL,
  `digimon_id` bigint(20) unsigned NOT NULL,
  `price` int(10) unsigned NOT NULL,
  `status` enum('active','sold','cancelled') NOT NULL DEFAULT 'active',
  `buyer_id` int(10) unsigned DEFAULT NULL,
  `created_at` int(10) unsigned NOT NULL,
  `completed_at` int(10) unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_trade_market` (`status`,`created_at`),
  KEY `idx_trade_seller` (`seller_id`,`status`),
  KEY `fk_trade_buyer` (`buyer_id`),
  KEY `fk_trade_digimon` (`digimon_id`),
  CONSTRAINT `fk_trade_buyer` FOREIGN KEY (`buyer_id`) REFERENCES `members` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_trade_digimon` FOREIGN KEY (`digimon_id`) REFERENCES `digimon_instances` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_trade_seller` FOREIGN KEY (`seller_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `world_map_blocks` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `world_key` varchar(24) NOT NULL,
  `area_key` varchar(64) NOT NULL,
  `xblock` int(11) NOT NULL,
  `yblock` int(11) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_block` (`world_key`,`area_key`,`xblock`,`yblock`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `world_map_positions` (
  `user_id` int(10) unsigned NOT NULL,
  `world_key` varchar(24) NOT NULL,
  `area_key` varchar(64) NOT NULL,
  `x` int(11) NOT NULL,
  `y` int(11) NOT NULL,
  `updated_at` int(10) unsigned NOT NULL DEFAULT 0,
  PRIMARY KEY (`user_id`,`world_key`,`area_key`),
  KEY `idx_area` (`world_key`,`area_key`,`updated_at`),
  CONSTRAINT `fk_worldpos_member` FOREIGN KEY (`user_id`) REFERENCES `members` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;















SET FOREIGN_KEY_CHECKS=1;
